using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class T01CorridorAudit {
 static string PathOf(Transform t)=>t.parent?PathOf(t.parent)+"/"+t.name:t.name;static float[] V(Vector3 v)=>new[]{v.x,v.y,v.z};
 static readonly Vector3 P=new Vector3(-17.23132775f,-82,-1.074689f);static readonly Quaternion Q=Quaternion.LookRotation(new Vector3(-.242535625f,0,.9701425f));const float L=13.4617394f;
 public static object Run(){var scene=SceneManager.GetActiveScene();if(scene.isDirty||Application.isPlaying)throw new Exception("Saved Edit scene required");var root=scene.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var group=root.Find("T01_Corridor_Finish");var repo=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));var o=repo+"/Docs/검수/2026-11-07_T01_Corridor/";var before=JObject.Parse(File.ReadAllText(o+"before.json"));var guides=root.Find("Facility_Floor_Guidance_R1");var meshes=group.GetComponentsInChildren<MeshFilter>().Concat(guides.GetComponentsInChildren<MeshFilter>()).Select(f=>f.sharedMesh).Distinct().ToArray();var meshReport=new List<object>();int bad=0,total=0;
 foreach(var m in meshes){int deg=0;var v=m.vertices;var t=m.triangles;for(int i=0;i<t.Length;i+=3)if(Vector3.Cross(v[t[i+1]]-v[t[i]],v[t[i+2]]-v[t[i]]).sqrMagnitude<1e-14f)deg++;bad+=deg;total+=t.Length/3;meshReport.Add(new{m.name,triangles=t.Length/3,degenerate=deg,boundsCenter=V(m.bounds.center),boundsSize=V(m.bounds.size)});}
 Physics.SyncTransforms();var blocked=new List<object>();var missing=new List<object>();int samples=0;foreach(float x in new[]{-.8f,0,.8f})for(float z=-1.2f;z<L+1.2f;z+=.10f){samples++;var p=P+Q*new Vector3(x,0,z);var ground=Physics.RaycastAll(p+Vector3.up*.20f,Vector3.down,.45f,~0,QueryTriggerInteraction.Ignore).Any(h=>h.collider.transform.IsChildOf(root)&&h.normal.y>.8f);if(!ground)missing.Add(new{x,z});var hit=Physics.OverlapCapsule(p+Vector3.up*.37f,p+Vector3.up*1.50f,.28f,~0,QueryTriggerInteraction.Ignore).Where(c=>c.transform.IsChildOf(root)&&!c.name.Contains("Floor")&&!c.name.Contains("Threshold")).ToArray();if(hit.Length>0)blocked.Add(new{x,z,hits=hit.Select(c=>PathOf(c.transform)).ToArray()});}
 var changes=new List<object>();var current=JArray.Parse(JsonConvert.SerializeObject(root.GetComponentsInChildren<Transform>(true).Select(t=>new{path=PathOf(t),position=V(t.localPosition),rotation=V(t.localEulerAngles),scale=V(t.localScale),active=t.gameObject.activeSelf}).ToArray()));foreach(var item in before["hierarchy"]){string path=(string)item["path"];if(path.Contains("/Pocket_Doors_Open/Door_B5-T01_1/"))continue;if(!current.Any(j=>JToken.DeepEquals(j,item)))changes.Add(new{path,reason="Missing or changed transform/active"});}
 var lights=root.GetComponentsInChildren<Light>(true).Select(l=>new{path=PathOf(l.transform),enabled=l.enabled,active=l.gameObject.activeInHierarchy,position=V(l.transform.position),rotation=V(l.transform.eulerAngles),localPosition=V(Quaternion.Inverse(Q)*(l.transform.position-P)),l.intensity,l.range,l.spotAngle,color=V(new Vector3(l.color.r,l.color.g,l.color.b)),type=l.type.ToString(),shadows=l.shadows.ToString()}).ToArray();var lightMap=JArray.Parse(JsonConvert.SerializeObject(lights));var lightChanges=before["lights"].Where(j=>!lightMap.Any(k=>JToken.DeepEquals(j,k))).Select(j=>(string)j["path"]).ToArray();
 // Check complete label rectangles against both guide strip edges, sampled every 2 cm.
 float clearance=float.MaxValue;int overlaps=0;var labels=group.Cast<Transform>().Where(t=>t.name.StartsWith("T01_C0")).ToArray();foreach(var mf in guides.GetComponentsInChildren<MeshFilter>()){var vs=mf.sharedMesh.vertices;for(int i=0;i<vs.Length-2;i+=2)for(int edge=0;edge<2;edge++){var a=mf.transform.TransformPoint(vs[i+edge]);var b=mf.transform.TransformPoint(vs[i+edge+2]);int steps=Mathf.CeilToInt(Vector3.Distance(a,b)/.02f);for(int k=0;k<=steps;k++){var p=Vector3.Lerp(a,b,(float)k/Mathf.Max(1,steps));foreach(var label in labels){var q=label.InverseTransformPoint(p);float dx=Mathf.Max(Mathf.Abs(q.x)-.3f,0),dz=Mathf.Max(Mathf.Abs(q.z)-.7f,0);float distance=Mathf.Sqrt(dx*dx+dz*dz);clearance=Mathf.Min(clearance,distance);if(distance<.001f)overlaps++;}}}}
 var player=scene.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));var result=new{scene=scene.path,meshReport,uniqueTriangles=total,degenerateTriangles=bad,missingMaterials=group.GetComponentsInChildren<Renderer>().Sum(r=>r.sharedMaterials.Count(m=>!m||!m.shader)),corridorSamples=samples,blocked,missingFloor=missing,labelGuideOverlapSamples=overlaps,labelGuideMinClearance=clearance,lightCount=lights.Length,lightChanges,protectedTransformChanges=changes,newBehaviours=group.GetComponentsInChildren<MonoBehaviour>(true).Length,newLights=group.GetComponentsInChildren<Light>(true).Length,playerPosition=V(player.transform.position),playerRotation=V(player.transform.eulerAngles),runInBackground=PlayerSettings.runInBackground};File.WriteAllText(o+"audit.json",JsonConvert.SerializeObject(result,Formatting.Indented));return new{degenerateTriangles=bad,uniqueTriangles=total,corridorSamples=samples,blocked=blocked.Count,missingFloor=missing.Count,lightChanges,protectedChanges=changes.Count,labelGuideMinClearance=clearance,labelGuideOverlapSamples=overlaps};}
}
